CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('bank','cash')),own_confirmed INTEGER NOT NULL DEFAULT 0,opening_balance_minor BIGINT,opening_balance_date DATE,currency TEXT NOT NULL DEFAULT 'RUB');
CREATE TABLE IF NOT EXISTS batches(id TEXT PRIMARY KEY,file_name TEXT NOT NULL,file_hash TEXT NOT NULL,profile TEXT NOT NULL,created_at TEXT NOT NULL,idempotency_key TEXT UNIQUE,rows_new INTEGER NOT NULL,rows_duplicate INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS coverage(id TEXT PRIMARY KEY,batch_id TEXT NOT NULL REFERENCES batches(id),account_id TEXT NOT NULL REFERENCES accounts(id),date_from DATE NOT NULL,date_to DATE NOT NULL,asserted_by_user INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS raw_transactions(id TEXT PRIMARY KEY,batch_id TEXT NOT NULL REFERENCES batches(id),source_row INTEGER NOT NULL,external_id TEXT,account_id TEXT NOT NULL REFERENCES accounts(id),booking_date DATE NOT NULL,amount_minor BIGINT NOT NULL CHECK(amount_minor != 0),currency TEXT NOT NULL,description TEXT NOT NULL,bank_type TEXT NOT NULL,counterparty TEXT,counterparty_account_ref TEXT,fingerprint TEXT NOT NULL,occurrence_index INTEGER NOT NULL,stable_key TEXT NOT NULL UNIQUE);
CREATE INDEX IF NOT EXISTS ix_raw_account_date ON raw_transactions(account_id,booking_date);
CREATE INDEX IF NOT EXISTS ix_raw_fingerprint ON raw_transactions(fingerprint);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,kind TEXT NOT NULL,resolution_status TEXT NOT NULL,resolution_source TEXT NOT NULL,coverage_status TEXT NOT NULL DEFAULT 'unknown',revision INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1,explanation TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT 'uncategorized',own_share_minor BIGINT,participant TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS event_raw(event_id TEXT NOT NULL REFERENCES events(id),raw_id TEXT NOT NULL UNIQUE REFERENCES raw_transactions(id),PRIMARY KEY(event_id,raw_id));
CREATE TABLE IF NOT EXISTS movements(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id),raw_id TEXT UNIQUE REFERENCES raw_transactions(id),account_id TEXT NOT NULL REFERENCES accounts(id),date DATE NOT NULL,amount_minor BIGINT NOT NULL,origin TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_movements_date ON movements(date);
CREATE TABLE IF NOT EXISTS effects(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id),date DATE NOT NULL,measure TEXT NOT NULL CHECK(measure IN ('expense','income')),amount_minor BIGINT NOT NULL,category TEXT);
CREATE INDEX IF NOT EXISTS ix_effects_date ON effects(date,measure);
CREATE TABLE IF NOT EXISTS receivables(id TEXT PRIMARY KEY,origin_event_id TEXT NOT NULL REFERENCES events(id),participant TEXT NOT NULL,original_minor BIGINT NOT NULL CHECK(original_minor > 0),created_date DATE NOT NULL);
CREATE TABLE IF NOT EXISTS settlements(id TEXT PRIMARY KEY,event_id TEXT NOT NULL UNIQUE REFERENCES events(id),receivable_id TEXT NOT NULL REFERENCES receivables(id),amount_minor BIGINT NOT NULL CHECK(amount_minor > 0),date DATE NOT NULL);
CREATE TABLE IF NOT EXISTS refunds(id TEXT PRIMARY KEY,refund_event_id TEXT NOT NULL UNIQUE REFERENCES events(id),purchase_event_id TEXT NOT NULL REFERENCES events(id),amount_minor BIGINT NOT NULL CHECK(amount_minor > 0));
CREATE TABLE IF NOT EXISTS questions(id TEXT PRIMARY KEY,event_id TEXT NOT NULL UNIQUE REFERENCES events(id),kind TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',impact_minor INTEGER NOT NULL DEFAULT 0,snoozed_at TEXT,evidence_signature TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS review_sessions(id TEXT PRIMARY KEY,batch_id TEXT REFERENCES batches(id),shown_ids TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS decisions(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id),command_id TEXT NOT NULL UNIQUE,before_json TEXT NOT NULL,after_json TEXT NOT NULL,created_at TEXT NOT NULL,undone_at TEXT);
CREATE TABLE IF NOT EXISTS rules(id TEXT PRIMARY KEY,merchant TEXT NOT NULL UNIQUE,category TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS weekly_reviews(period_from TEXT PRIMARY KEY,period_to TEXT NOT NULL,seen_at TEXT,last_seen_import_cursor TEXT);
CREATE TABLE IF NOT EXISTS previews(id TEXT PRIMARY KEY,created_at TEXT NOT NULL,payload_json TEXT NOT NULL);
